import re, os
root='.'
pat_copy = re.compile(r'(copy_from_user|memdup_user\(|vmemdup_user\(|simple_write_to_buffer)')
pat_term = re.compile(r'(\w+)\s*\[\s*(\w+)\s*\]\s*=\s*(\'\\0\'|0)\s*;')
pat_clamp = re.compile(r'(\w+)\s*=\s*min(?:_t\(\s*\w+\s*,\s*)?\(\s*([^,()]+),\s*sizeof\(([^)]+)\)\s*\)')
results=[]
for dirpath,dirs,files in os.walk(root):
    dirs[:] = [d for d in dirs if d not in ('.git',)]
    for f in files:
        if not f.endswith(('.c','.h')): continue
        p=os.path.join(dirpath,f)
        try: lines=open(p,encoding='utf-8',errors='ignore').read().splitlines()
        except: continue
        # find terminator writes buf[i]=0 and check for clamp & usercopy in preceding 25 lines
        for i,l in enumerate(lines):
            m=pat_term.search(l)
            if not m: continue
            var,idx=m.group(1),m.group(2)
            ctx='\n'.join(lines[max(0,i-25):i+1])
            if not pat_copy.search(ctx): continue
            # clamp where idx var assigned min(x, sizeof(buf))
            mc=None
            for mm in pat_clamp.finditer(ctx):
                if mm.group(1)==idx:
                    mc=mm
            # check declared array size of var nearby
            decl=None
            for j in range(max(0,i-40),i):
                dm=re.search(r'\b(?:char|u8|unsigned char|__u8)\s+'+re.escape(var)+r'\s*\[\s*(\d+|sizeof\([^)]*\)|[A-Z_0-9]+)\s*\]', lines[j])
                if dm: decl=(j+1,dm.group(1))
            if mc or decl:
                results.append((p,i+1,var,idx,'clamp' if mc else 'nodecl', decl, l.strip()))
for r in results:
    print(r)
EOF

